/**
 * Parts of a Bird (td-9c9655). Geometry is generated by scripts/bird-parts/
 * into ./geometry/*.json; the names and ID text live in one module per bird.
 */

export type Layer = "main" | "feathers";

export const PART_GROUPS = ["Head", "Bill & legs", "Upperparts", "Wing", "Underparts", "Tail"] as const;
export type PartGroup = (typeof PART_GROUPS)[number];

/** Fixed natural colours (the drawing sits on a light plate in every theme). */
export type Tone =
  | "pale" | "light" | "mid" | "wing" | "dark" | "darker" | "bill" | "leg" | "legyellow" | "billyellow"
  | "accent2" | "water" | "gullgray" | "legpink" | "eye" | "perch" | "accent" | "orbital" | "mallardgreen" | "chestnut";

export interface PartText {
  id: string;
  name: string;
  aka?: string;
  group: PartGroup;
  /** One or two sentences: what to look at here when identifying a bird. */
  lookFor: string;
  /** Honesty note, e.g. hidden at rest. */
  visibility?: string;
}

export interface Source {
  label: string;
  url: string;
  /** Who made it and its licence, for reference photos. */
  credit?: string;
}

export interface DiagramText {
  id: string;
  title: string;
  model: { species: string; age: string; pose: string };
  intro: string;
  /** Reference photos (proportions only; never shown) and fact references. */
  sources: Source[];
  parts: PartText[];
}

export interface Shape {
  d: string;
  tone: Tone;
}

export interface PartGeometry extends Shape {
  id: string;
  layers: Layer[];
}

export interface Inset {
  cx: number;
  cy: number;
  r: number;
  label: string;
}

export interface DiagramGeometry {
  id: string;
  viewBox: number[];
  drawOrder: string[];
  parts: PartGeometry[];
  under: Shape[];
  over: Shape[];
  outline: string | null;
  insets: Inset[];
}

export type BirdPart = PartText & PartGeometry;

export interface BirdDiagram extends Omit<DiagramText, "parts"> {
  viewBox: string;
  /** Bottom to top; the topmost visible part wins a tap. */
  parts: BirdPart[];
  /** Part ids in reading order (as written in the text module), for the lists. */
  listOrder: string[];
  under: Shape[];
  over: Shape[];
  outline: string | null;
  insets: Inset[];
}
